from os import path, stat
import json
import base64
import logging
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable
from taf.sbts.oam.coam.admin.utils import raise_value_error


class ParameterEditorInterface21B(object):
    def activate_plan(self, plan_id, timeout=300, detailed_output=False):
        """Activate previously commissioned plan.commissioned

        :param string plan_id: Plan ID (delta dist name)
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param bool detailed_output: return full request response when True, defaults set to False.

        :return Union[str,dict]: Status of the operation or full response dict

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-activatePlan.html
        """

        response = self._api_client.execute_customer_procedure("activatePlan", {"deltaDN": plan_id}, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def perform_delta_recommissioning(self, delta_file, skip_parameter_relation_errors=False, should_activate=True, timeout=300):
        """Perform delta recommissioning.

        :param string delta_file: Delta JSON or path to JSON file.
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors.
        :param boolean should_activate: should automatically activate plan.
        :param int timeout: Time to wait for positive procedure result
        :return dict: recommissioning result

        | Delta JSON is send to Admin API as "planObjects" parameter of "recomission" procedure.
        | For detailed instruction how to create delta JSON see Admin API doc:
        | https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-recommission.html

        **SAMPLE DELTA:**

        ::

            [
                {
                    "distName": "MRBTS-1/LNBTS-1/LNMME-0",
                    "operation": "update",
                    "parameters": [
                        {
                            "parameterName": "ipAddrPrim",
                            "value": "10.0.1.99",
                            "operation": "update"
                        }
                    ]
                }
            ]
        """
        delta = ""

        if path.isfile(delta_file):
            if stat(delta_file).st_size == 0:
                logging.error("Provided delta file is empty!")
            with open(delta_file, 'r') as f:
                delta_file = f.read()
        else:
            logging.info(f"No file found at path '{delta_file}'. Assuming input is a JSON string.")
            if not delta_file.strip().startswith("["):
                logging.warning("Input does not appear to be a valid JSON array. Please verify the format.")

        try:
            delta = json.loads(delta_file)
        except json.JSONDecodeError as e:
            logging.error("Invalid JSON syntax: {}".format(str(e)))
            raise ValueError(f"Failed to parse delta JSON: {str(e)}") from e

        parameters = {"planObjects": delta, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True

        return self._api_client.execute_procedure("recommission", parameters, timeout)

    def perform_ncf_commissioning(self, ncf_filepath, timeout=120, detailed_output=False):
        """
        Perform NCF commissioning.

        :param str ncf_filepath: Filepath to NCF file.
        :param int timeout: (optional) Timeout for the operation, defaults to 120
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed or full response dict

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-activeNCF.html
        """
        response = self._api_client.execute_customer_procedure('activeNCF',
                                                               parameters={},
                                                               timeout=timeout,
                                                               input_file_name=ncf_filepath)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def add_rat(self, rat_technology, plan_scf_file, rat_scf_file, output_scf, timeout=60, band=None, **kwargs):
        """Add RAT technology into given SCF file

        :param string rat_technology: Name of RAT being added. ["GSM"|"WCDMA"|"LTE"|"NR"].
        :param string plan_scf_file: SCF file path with plan configuration.
        :param string rat_scf_file: SCF file path with RAT specific configuration.
        :param string output_scf: Output SCF file path
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param string band: (optional) Support multiple bands, separated by comma, i.e.: "1,2"

        :return dict: dict with list of skipped objects.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-addRat.html
        """

        parameters = {"ratTechnology": rat_technology, "band": band}

        skipped_objects = self._api_client.execute_offline_procedure("addRat", parameters, timeout,
                                                                     plan_scf_file=plan_scf_file,
                                                                     rat_scf_file=rat_scf_file,
                                                                     output_file_name=output_scf)

        return skipped_objects

    def migrate_scf(self, input_scf_file, output_scf_file, timeout=60):
        """Migrate SCF

        :param string input_scf_file: Input SCF file path.
        :param string output_scf_file: Output SCF file path.
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :return string: Result of the operation.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-migrateScf.html
        """

        return self._api_client.execute_offline_procedure("migrateScf", {}, timeout, input_file_name=input_scf_file,
                                                          output_file_name=output_scf_file)

    def perform_commissioning(self, bts_id=None, scf_file=None, skip_parameter_relation_errors=False, should_activate=True,
                              timeout=300):
        """
                Perform commissioning.

                :param string bts_id: BTS ID
                :param str scf_file: Path to the scf file.
                :param bool skip_parameter_relation_errors: Skip parameter relation errors.
                :param bool should_activate: Should automatically activate plan.
                :param Union[int,str] timeout: Timeout for the operation.
                :return str: Commissioning status (completed, ongoing or failed).
                             More details (content of requestMessage is returned data):
                             https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-downloadPlan.html
        """
        parameters = {"shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True
        if bts_id:
            parameters["btsId"] = bts_id
        status = self._api_client.execute_procedure("downloadPlan", parameters, timeout, input_file_name=scf_file)
        if status is None:
            raise DataNotAvailable("Commissioning status has not been provided by M-Plane.")
        return status

    def perform_parameter_recommissioning(self, dist_name, parameter, operation, value,
                                          skip_parameter_relation_errors=False, should_activate=True, timeout=300):
        """
        Perform parameter recommissioning, update and delete operation can be used.

        :param string dist_name: Object dist name ie. "MRBTS-1/LNBTS-1/LNMME-0"
        :param string parameter: Parameter name ie. "ipAddrPrim"
        :param string operation: Parameter operation (update or delete)
        :param Union[str,list] value: Parameter value ie. "10.0.1.99" or [{"eea1":0, "eea0":1, "eea3":8, "eea2":0}]
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :raises taf.sbts.oam.coam.admin.legacy.exceptions.AdminApiProcedureFailureException: Will be raised if
            recommissioning fails
        :return dict: Recommissioning status
                More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-recommission.html

        For example, dict as blow will be returned if recommission success

        ::

            {
                'commissioningResult': {
                     'isGoingToTriggerReset': False,
                     'activationResult': {
                         'resultNode': {
                             'distName': '/MRBTS-1/RAT-1/URI-1/SESSION-17/PLAN_ACTIVATE_IND-1/PLAN_ACTIVATE_RESULT-1',
                             'parameters': {
                                 'rejectedObjects': [],
                                 'resetCoverage': 'None',
                                 'result': 'Success'
                                 }
                            },
                        'indicationDistName': '/MRBTS-1/RAT-1/URI-1/SESSION-17/PLAN_ACTIVATE_IND-1'
                     }
                 },
                'validationResult': {
                    'niddValidationResult': {
                        'status': 'OK',
                        'logs': {
                            'skippedElements': None,
                            'missingObjectsErrors': None,
                            'definitionErrors': None,
                            'maxOccurrencesErrors': None
                        }
                    },
                    'pdlValidationResult': {
                        'status': 'OK',
                        'logs': {
                            'hardwareErrors': [],
                            'relationErrors': []
                        }
                    }
                },
                'modifiedObjectsDistNames': {
                     'deleted': [],
                     'modified': ['MRBTS-111/LNBTS-1/LNADJGNB-1']
                }
            }
        """
        delta = [{'distName': dist_name,
                  'operation': 'update',
                  'parameters': [{'operation': operation,
                                  'parameterName': parameter,
                                  'value': value}]}]
        parameters = {"planObjects": delta, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True
        status = self._api_client.execute_procedure("recommission", parameters, timeout)
        if status is None:
            raise DataNotAvailable("Recommissioning status has not been provided by M-Plane.")
        return status

    def perform_object_recommissioning(self, dist_name, parameter, operation, skip_parameter_relation_errors=False,
                                       should_activate=True, timeout=300):
        """
        Perform object recommissioning, create, update and delete operation can be used.

        :param string dist_name: Object dist name ie. "MRBTS-111/LNBTS-40/LNCEL-11/LNRELGNBCELL-0"
        :param list parameter: list of dicts, delete operation will be executed if parameter is an empty list
        :param string operation: Object operation (create, update or delete)
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :raises taf.sbts.oam.coam.admin.legacy.exceptions.AdminApiProcedureFailureException: Will be raised if
            recommissioning fails
        :return dict: Recommissioning status
                More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-recommission.html
        """
        delta = [{'distName': dist_name,
                  'operation': operation,
                  'parameters': parameter}]
        parameters = {"planObjects": delta, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True
        status = self._api_client.execute_procedure("recommission", parameters, timeout)
        if status is None:
            raise DataNotAvailable("Recommissioning status has not been provided by M-Plane.")
        return status

    def validate_scf(self, scf_file, validation_type=None, skip_parameter_relation_errors=False, timeout=60, detailed_output=True):
        """
        Validate SCF.

        :param str scf_file: Path to the SCF file.
        :param string validation_type: possible values (NIDD_AND_RELATIONS, DETECTED_HW)
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param int timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True

        :return dict: SCF validation result or full API response when detailed_output=True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-validateScf.html
        """
        parameters = {"skipParameterRelationErrors": skip_parameter_relation_errors}
        if validation_type:
            if validation_type.upper() not in ("NIDD_AND_RELATIONS", "DETECTED_HW"):
                raise_value_error(param="validation_type",
                                  value=str(validation_type),
                                  subpage="tutorial-validateScf.html")
            parameters["validationType"] = validation_type
        result = self._api_client.execute_customer_procedure("validateScf", parameters, timeout,
                                                             input_file_name=scf_file)
        return result if detailed_output else result.get(self._provided_content.request_message)

    def get_scf(self, export_type=None, timeout=120, parameters_save_variant=None, detailed_output=False, **kwargs):
        """
        Get SCF file content

        :param str export_type: one of configuration, configurationAndRuntimeObjects, runtimeObjects.
                                None means default Admin API behavior.
        :param int timeout: (optional) Timeout for the operation. Defaults set to 120s.
        :param str parameters_save_variant: one of actualValues, plannedValues. None means default Admin API behavior.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return: Union[str,dict] file content or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-generateScf.html
        """

        if export_type not in (None, "configuration", "configurationAndRuntimeObjects", "runtimeObjects"):
            raise_value_error(param="export_type",
                              value=str(export_type),
                              subpage="tutorial-generateScf.html")

        if parameters_save_variant not in (None, "actualValues", "plannedValues"):
            raise_value_error(param="parameters_save_variant",
                              value=str(parameters_save_variant),
                              subpage="tutorial-generateScf.html")

        parameters = {"exportType": export_type, "parametersSaveVariant": parameters_save_variant}

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_customer_procedure(name="generateScf",
                                                               parameters=parameters,
                                                               timeout=timeout)

        scf = response.get(self._provided_content.output_file_content)

        if not scf:
            raise DataNotAvailable("SCF file content has not been provided by M-Plane.")

        return response if detailed_output else base64.b64decode(scf).decode('utf-8')

    def get_current_scf_file(self, local_dir_path, file_name, export_type=None, timeout=120,
                             parameters_save_variant=None, **kwargs):
        """
        Save a current SCF to a file and get a path to this file.

        :param str local_dir_path: Path to directory to store final SCF.
        :param str file_name: File name of final SCF.
        :param int timeout: Timeout for the operation.
        :param str export_type: one of configuration, configurationAndRuntimeObjects, runtimeObjects.
                                None means default Admin API behavior.
        :param str parameters_save_variant: one of actualValues, plannedValues. None means default Admin API behavior.
        :return str: Path to the file with current SCF content.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-generateScf.html
        """
        if export_type not in (None, "configuration", "configurationAndRuntimeObjects", "runtimeObjects"):
            raise_value_error(param="export_type",
                              value=str(export_type),
                              subpage="tutorial-generateScf.html")

        if parameters_save_variant not in (None, "actualValues", "plannedValues"):
            raise_value_error(param="parameters_save_variant",
                              value=str(parameters_save_variant),
                              subpage="tutorial-generateScf.html")

        parameters = {"exportType": export_type, "parametersSaveVariant": parameters_save_variant}

        parameters = {k: v for k, v in parameters.items() if v is not None}

        target_file_name = path.join(local_dir_path, file_name)

        self._api_client.execute_customer_procedure(name="generateScf",
                                                    parameters=parameters,
                                                    timeout=timeout,
                                                    output_file_name=target_file_name)
        return target_file_name
